public static string NextVersion(string current, IReadOnlyList<string> commitTitles)
{
    // Удаляем префикс 'v' (если есть), разбиваем строку по точкам и преобразуем части в целые числа.
    // Ожидаем формат версии вида "v1.2.3" или "1.2.3".
    var parts = current.TrimStart('v').Split('.').Select(int.Parse).ToArray();

    // Проверяем, что версия состоит ровно из трёх частей (major, minor, patch).
    // Если формат неверный — выбрасываем исключение.
    if (parts.Length != 3)
        throw new FormatException($"Bad version: {current}");

    // Распаковываем массив частей в отдельные переменные для удобства работы.
    var (major, minor, patch) = (parts[0], parts[1], parts[2]);

    // Проверяем наличие "BREAKING CHANGE" в заголовках коммитов или наличие '!' перед двоеточием
    // (согласно конвенции Conventional Commits, это означает breaking change).
    // Если найдено — увеличиваем major версию.
    // Особый случай: если major == 0, то по конвенции SemVer breaking changes увеличивают minor версию,
    // так как major 0 означает нестабильный API.
    if (commitTitles.Any(t => t.Contains("BREAKING CHANGE") || t.Split(':')[0].EndsWith("!")))
        return major == 0 ? $"v0.{minor + 1}.0" : $"v{major + 1}.0.0";

    // Проверяем наличие коммитов с типом "feat" (новые функции).
    // Если найдено — увеличиваем minor версию, сбрасывая patch в 0.
    if (commitTitles.Any(t => t.StartsWith("feat")))
        return $"v{major}.{minor + 1}.0";

    // Если нет ни breaking changes, ни новых фич, но есть коммиты (например, fix, docs и т.д.),
    // то увеличиваем patch версию.
    // Однако, если список коммитов пуст, возвращаем текущую версию без изменений.
    if (commitTitles.Count == 0)
        return current;

    // Увеличиваем patch версию (для исправлений, рефакторингов и других некритичных изменений).
    return $"v{major}.{minor}.{patch + 1}";
}
