	// уже завершил работу и не читает из канала.
	errCh := make(chan error, 1)

	// Запускаем HTTP-сервер в отдельной горутине, так как ListenAndServe блокирует поток.
	go func() {
		// Запускаем сервер. Если произошла ошибка, и она не связана с штатным закрытием
		// сервера (http.ErrServerClosed), отправляем ошибку в канал.
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			errCh <- err
		}
	}()

	// Создаём канал для приёма сигналов завершения процесса (Ctrl+C, kill и т.д.).
	stop := make(chan os.Signal, 1)
	// Регистрируем обработчик сигналов SIGINT и SIGTERM.
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)

	// Ожидаем либо ошибку запуска сервера, либо сигнал завершения.
	select {
	case err := <-errCh:
		// Если сервер упал с ошибкой, немедленно возвращаем её.
		return err
	case <-stop:
