/**
 * Функция для ленивой загрузки изображений (lazy loading).
 * Использует IntersectionObserver для отслеживания видимости изображений
 * и загружает их только тогда, когда они приближаются к области видимости.
 *
 * @param root - Корневой элемент, внутри которого ищутся изображения. По умолчанию — весь документ.
 * @param margin - Отступ (rootMargin) для IntersectionObserver, определяющий,
 *                 на каком расстоянии от области видимости начинать загрузку.
 * @returns Функция для отключения наблюдателя (cleanup function).
 */
export function lazyLoadImages(root: ParentNode = document, margin = "200px"): () => void {
  // Находим все изображения с атрибутом data-src внутри указанного корневого элемента.
  // Атрибут data-src содержит URL реального изображения, которое нужно загрузить.
  const images = Array.from(root.querySelectorAll<HTMLImageElement>("img[data-src]"));

  // Вспомогательная функция для загрузки конкретного изображения:
  // 1. Устанавливает src из data-src.
  // 2. Удаляет атрибут data-src, чтобы избежать повторной загрузки.
  const load = (img: HTMLImageElement) => {
    img.src = img.dataset.src!;
    img.removeAttribute("data-src");
  };

  // Проверка поддержки IntersectionObserver в текущем браузере.
  // Если API не поддерживается, сразу загружаем все изображения и возвращаем
  // пустую функцию-заглушку для cleanup.
  if (!("IntersectionObserver" in window)) {
    images.forEach(load);
    return () => {};
  }

  // Создаём экземпляр IntersectionObserver.
  // Колбэк вызывается, когда наблюдаемые элементы пересекают область видимости
  // с учётом заданного отступа (rootMargin).
  const observer = new IntersectionObserver((entries) => {
    for (const entry of entries) {
      // Пропускаем элементы, которые не пересекают область видимости.
      if (!entry.isIntersecting) continue;

      // Загружаем изображение, которое стало видимым (или приближается к видимости).
      load(entry.target as HTMLImageElement);

      // Прекращаем наблюдение за этим элементом, так как он уже загружен.
      observer.unobserve(entry.target);
    }
  }, { rootMargin: margin }); // Отступ определяет, за сколько пикселей до появления
                              // в области видимости начинать загрузку.

  // Начинаем наблюдение за каждым найденным изображением.
  images.forEach((img) => observer.observe(img));

  // Возвращаем функцию для отключения наблюдателя.
  // Это полезно при размонтировании компонента или очистке ресурсов.
  return () => observer.disconnect();
}
```

