/// Разбирает строку с именем Docker-образа и возвращает кортеж из:
/// (реестр, репозиторий, тег, дайджест).
/// Возвращает `None`, если формат строки некорректен.
pub fn parse_image(s: &str) -> Option<(&str, &str, Option<&str>, Option<&str>)> {
    // Шаг 1: Извлекаем дайджест (sha256), если он присутствует.
    // Формат дайджеста: `@sha256:<хеш>`.
    // Если символ '@' найден, но после него не идёт "sha256:", считаем строку невалидной.
    // Если '@' нет, дайджест отсутствует (None).
    let (rest, digest) = match s.split_once('@') {
        Some((r, d)) if d.starts_with("sha256:") => (r, Some(d)),
        Some(_) => return None,
        None => (s, None),
    };

    // Шаг 2: Извлекаем тег из оставшейся части строки.
    // Тег обычно идёт после последнего двоеточия, но только если после него нет слэша
    // (чтобы не перепутать с портом в имени реестра, например `localhost:5000/image`).
    // Если тег не найден или содержит '/', считаем, что тега нет.
    let (name, tag) = match rest.rsplit_once(':') {
        Some((n, t)) if !t.contains('/') => (n, Some(t)),
        _ => (rest, None),
    };

    // Шаг 3: Определяем реестр и репозиторий.
    // Если в имени есть '/', и первая часть содержит точку, двоеточие или равна "localhost",
    // то это явное указание реестра.
    // Иначе используем реестр по умолчанию — "docker.io".
    let (registry, repository) = match name.split_once('/') {
        Some((r, p)) if r.contains('.') || r.contains(':') || r == "localhost" => (r, p),
        _ => ("docker.io", name),
    };

    // Шаг 4: Валидация.
    // Репозиторий не может быть пустым.
    // Тег не может быть пустой строкой (например, `image:`).
    if repository.is_empty() || tag == Some("") {
        return None;
    }

    // Возвращаем разобранные компоненты.
    Some((registry, repository, tag, digest))
}
